//! ♻️ Same-Source fixture retains the terminal failure before its Handoff move.
use super::*;
use semio_framework_value_native_decoding::{OriginalRetirementFailure,retirement::controlled::ControlledRetirement};
struct State<'owner>{failure:&'owner mut Option<NativeTerminalFailureOutput>,controlled:Option<ControlledRetirement<NativeTerminalFailureOutput>>}
struct Producer;
impl OriginalEffectProducer for Producer{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'turn,'source>=&'turn mut State<'source> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn receive<'reply,'turn,'source>(&mut self,state:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'source:'turn{if let Some(controlled)=state.controlled.as_mut(){controlled.step_into(4096,effect,reply)}else{NativeTerminalFailureOutput::admit_retirement_into(state.failure,&mut state.controlled,effect,reply)}}
 fn recover<'reply,'turn,'source>(&mut self,state:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'source:'turn{if let Some(controlled)=state.controlled.as_mut(){controlled.recover_step_into(4096,effect,reply)}else{NativeTerminalFailureOutput::admit_retirement_into(state.failure,&mut state.controlled,effect,reply)}}
}
pub(super) struct Actor<'owner>{state:State<'owner>,producer:Option<OriginalEffectAuthority<Producer>>,action:Option<OriginalEffectAction<RetainedCloneStep,OriginalRetirementFailure>>,reply:Option<RetainedCloneStep>,returned:Option<Producer>}
impl<'owner> Actor<'owner>{
 pub(super) fn new(failure:&'owner mut Option<NativeTerminalFailureOutput>)->Self{Self{state:State{failure,controlled:None},producer:Some(OriginalEffectAuthority::new(Producer)),action:None,reply:None,returned:None}}
 pub(super) fn transfer(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->bool{bank.transfer_terminal_failure(handoff,self.state.failure.as_mut().expect("original failure destination"),observe).unwrap()}
 pub(super) fn failure(&self)->Option<&semio_framework_value_native_decoding::OriginalReceivingPrimary>{self.state.failure.as_ref().and_then(NativeTerminalFailureOutput::failure)}
 pub(super) fn release_demand(&self)->Option<RetirementDemand>{self.state.failure.as_ref().unwrap().receipt_completion_release_demand().unwrap()}
 pub(super) fn demand(&self)->RetirementDemand{match self.state.controlled.as_ref(){Some(controlled)=>controlled.next_demand(4096).unwrap(),None=>NativeTerminalFailureOutput::retirement_admission_demand()}}
 pub(super) fn work(&self)->u64{match self.state.controlled.as_ref(){Some(controlled)=>controlled.next_computational_work(4096).unwrap(),None=>1}}
 pub(super) fn empty(&self)->bool{self.state.controlled.as_ref().is_some_and(ControlledRetirement::terminal_is_empty)}
 pub(super) fn needs_birth(&self)->bool{self.state.controlled.as_ref().is_some_and(ControlledRetirement::requires_original_birth)}
 pub(super) fn birth(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){let grant=bank.wallet.lock().unwrap().left;bank.run_frame(frame,Some(recipient),observe,|bank,native|bank.run(native,|native|native.with_retirement(grant,|retirement|retirement.with_original_close(|loan|{match self.state.controlled.as_mut().unwrap().step_original_birth(loan,grant){RetainedWorkPoll::Pending{..}=>{},RetainedWorkPoll::Complete(turn)=>{if let Err(error)=turn.result{panic!("original controlled birth refused: {error:?}")}}}Ok::<_,ValueError>(())})))).unwrap()}
 pub(super) fn reply(&self)->Option<&RetainedCloneStep>{self.reply.as_ref()}
 pub(super) fn finish_action(&mut self){self.producer.as_mut().unwrap().finish(&mut self.action).unwrap()}
 pub(super) fn producer_demand()->RetirementDemand{OriginalEffectAuthority::<Producer>::producer_transfer_demand().unwrap()}
 pub(super) fn finished(&self)->bool{self.state.failure.is_none()&&self.state.controlled.is_none()&&self.producer.is_none()&&self.action.is_none()&&self.reply.is_none()&&self.returned.is_none()}
}

impl PaidAction{
 pub(super) fn retire_terminal_receipt(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,physical,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,self.maximum_work,&mut self.actual)?;self.progress=actor.state.failure.as_mut().unwrap().retire_receipt_completion(physical,payout.as_ref().unwrap(),&mut effect).result?;Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(super) fn retirement_producer(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->bool{bank.with_terminal_loans(|work,physical|{let ready=frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{if let Some(claim)=self.claim.take(){claim?;if work.partial_pending(self.work)?{assert!(work.settle_partial_into(self.work,&mut self.partial)?);assert!(self.partial.as_ref().unwrap().source_refusal().is_none());drop(self.partial.take())}}let grant=payout.as_ref().unwrap().grant().unwrap();let spent=work.performed_total(self.work)?;let remaining=u64::try_from(u128::from(self.maximum_work).checked_sub(spent).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"original retirement Work exceeded its quote"))?).map_err(|_|ValueError::invariant("original retirement Work window overflow"))?;let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,remaining,&mut self.actual)?;let mut context=&mut actor.state;let ready=actor.producer.as_mut().unwrap().drive(&mut context,&mut effect,&mut actor.action)?;if ready{self.progress=Some(match actor.action.as_ref().unwrap().recorded_reply().unwrap(){Ok(step)=>step.progress(),Err(_)=>panic!("original controlled retirement retained a refusal")})}Ok::<_,ValueError>(ready)}).unwrap();Ok(ready)}).unwrap()}
 pub(super) fn transfer_retirement_reply(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,1,&mut self.actual)?;let producer=actor.producer.as_ref().unwrap();let context=&mut actor.state;self.progress=producer.replace_copy_success_into(&context,actor.action.as_mut().unwrap(),&mut actor.reply,&mut effect).result?;assert!(self.progress.is_some());Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(super) fn retirement_reply_demand()->RetirementDemand{OriginalEffectAuthority::<Producer>::copy_success_demand().unwrap()}
 pub(super) fn release_controlled(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,1,&mut self.actual)?;assert!(actor.empty());assert!(semio_framework_value_native_decoding::ErasedSnapshotRetirement::native_header_release(actor.state.controlled.as_ref().unwrap()).is_some());assert!(effect.performed(1)?);drop(actor.state.controlled.take());self.progress=Some(RetainedCloneProgress{copied_items:1,copied_bytes:Self::controlled_release_demand().copy_bytes,..Default::default()});Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(super) fn controlled_release_demand()->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<ControlledRetirement<NativeTerminalFailureOutput>>>(),depth:1,..Default::default()}}
 pub(super) fn transfer_retirement_producer(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,1,&mut self.actual)?;let context=&mut actor.state;self.progress=OriginalEffectAuthority::transfer_producer(&mut actor.producer,&context,&mut actor.returned,&mut effect).result?;Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(super) fn release_retirement_producer(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,1,&mut self.actual)?;assert!(effect.performed(1)?);drop(actor.returned.take());self.progress=Some(RetainedCloneProgress{copied_items:1,copied_bytes:Self::producer_release_demand().copy_bytes,..Default::default()});Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(super) fn producer_release_demand()->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<Producer>>(),depth:1,..Default::default()}}
}

impl PaidAction{
 pub(super) fn release_retirement_reply(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,actor:&mut Actor<'_>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,payout|{let grant=payout.as_ref().unwrap().grant().unwrap();let mut scope=work.performed_scope(self.work,&mut self.receipt,&mut self.claim)?;let mut effect=scope.effect(grant,1,&mut self.actual)?;assert!(actor.reply.is_some());assert!(effect.performed(1)?);drop(actor.reply.take());self.progress=Some(RetainedCloneProgress{copied_items:1,copied_bytes:Self::reply_release_demand().copy_bytes,..Default::default()});Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(super) fn reply_release_demand()->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<RetainedCloneStep>>(),depth:1,..Default::default()}}
}
